// Bare kit: controller, motors, battery cells, power and wiring are unresolved. These are sensor mounting layouts only.
// Mechanical candidate; actual mounting interfaces are declared below.
Robot mount_3pi_imu_low {
    intent "Low open MinIMU cassette with explicit robot axes"

    Diff_two_caster chassis(ref = "pololu_3pi_plus_chassis_kit")
    Standard wheel_left(ref = "pololu_wheel_32x7mm_white", glue = (0, 0.0427, 0, 0, 1, 0))
    Standard wheel_right(ref = "pololu_wheel_32x7mm_white", glue = (0, -0.0427, 0, 0, -1, 0))

    Mount device1_sensor_support(ref = "robotdsl_3pi_imu_low", on = @core/chassis, at = "rear_sensor_pair", by = "under_holes")

    IMU device1_sensor_1(ref = "pololu_minimu_9_v6", on = @core/device1_sensor_support, at = "sensor_holes", by = "mounting_holes")
}

